const q = $('Embed customer photo').first().json.embedding && $('Embed customer photo').first().json.embedding.values;
const img = $('Photo request').first().json.image_url;
if (!q) return [{ json: { desc: {}, candidates: [], imageUrls: img, list: '', found: 0, error: 'embed failed' } }];
const fresh = (r) => r.model && (Date.now() - new Date(r.updatedAt).getTime() < 3 * 86400000);
const cat = new Map();
for (const i of $input.all()) { const r = i.json; if (fresh(r)) cat.set(String(r.group_id), r); }
const dot = (a, b) => { let s = 0; for (let i = 0; i < a.length; i++) s += a[i] * b[i]; return s; };
const nq = Math.sqrt(dot(q, q));
const scored = [];
for (const it of $('Get photo index').all()) {
  const row = it.json; const c = cat.get(String(row.group_id)); if (!c) continue;
  let v; try { v = JSON.parse(row.vec); } catch (e) { continue; }
  scored.push({ c, s: dot(q, v) / (nq * Math.sqrt(dot(v, v))), img: row.img_url });
}
scored.sort((a, b) => b.s - a.s);
const isGtx = (c) => /gore[\s-]*tex/i.test(String(c.model || ''));
const top = scored.slice(0, 6);
const have = new Set(top.map(x => String(x.c.group_id)));
const extra = scored.filter(x => isGtx(x.c) && x.c.in_stock_count > 0 && !have.has(String(x.c.group_id))).slice(0, 3);
const all = top.concat(extra);
const imageUrls = [img].concat(all.map(x => x.img)).join(',');
const list = all.map((x, i) => 'Фото ' + (i + 2) + ' = кандидат ' + (i + 1) + ': ' + x.c.model).join('\n');
return [{ json: { desc: {}, candidates: all.map(x => x.c), sims: all.map(x => x.s.toFixed(3)), imageUrls, list, found: all.length, indexed: scored.length } }];

const sl = $('Shortlist candidates').first().json;
const d = $input.first().json;
const raw = (d.content?.parts || []).map(p => p.text || '').join('') || d.text || '';
let items = [];
let custColors = '', custBrand = '', custWP = false, custWarm = false;
try { const m = String(raw).replace(/```json|```/g, '').match(/\{[\s\S]*\}/); const j = JSON.parse(m ? m[0] : raw); items = Array.isArray(j.items) ? j.items : []; custColors = j.customer_colors || ''; custBrand = String(j.customer_brand || '').trim(); custWP = j.customer_waterproof === true; custWarm = j.customer_warm === true; } catch (e) { items = []; }
let hint = ''; try { hint = String($('Photo request').first().json.hint || ''); } catch (e) {}
const sm = hint.match(/(?<![0-9])(3[4-9]|4[0-9])(?![0-9])/);
const wantSize = sm ? sm[1] : '';
const hasSize = (c) => wantSize && String(c.sizes_in_stock || '').split(/[^0-9]+/).includes(wantSize);
const isGtx = (c) => /gore[\s-]*tex/i.test(String(c.model || ''));
let rows = items.map(x => ({ c: sl.candidates[Number(x.n) - 1], n: Number(x.n), x })).filter(o => o.c).map(o => {
  const verdict = (o.x.same_model === true && o.x.same_colorway === true) ? 'exact' : (o.x.same_model === true ? 'same_model_other_color' : (o.x.similar_style === true ? 'similar' : 'different'));
  return { c: o.c, n: o.n, x: Object.assign({}, o.x, { verdict }) };
}).filter(o => o.x.verdict !== 'different');
if (custWP && rows.some(o => isGtx(o.c))) rows = rows.filter(o => isGtx(o.c) || o.x.verdict !== 'similar');
const order = { exact: 0, same_model_other_color: 1, similar: 2 };
rows.sort((a, b) => order[a.x.verdict] - order[b.x.verdict] || (custWP ? Number(isGtx(b.c)) - Number(isGtx(a.c)) : 0) || (Number(!!hasSize(b.c)) - Number(!!hasSize(a.c))) || (Number(b.c.in_stock_count > 0) - Number(a.c.in_stock_count > 0)) || (a.n - b.n));
const label = { exact: 'ВІРОГІДНИЙ ЗБІГ (схожа модель і колір)', same_model_other_color: 'ТА САМА МОДЕЛЬ, ІНШИЙ КОЛІР', similar: 'СХОЖА, АЛЕ ІНША МОДЕЛЬ' };
const fmt = (o) => label[o.x.verdict] + ': ' + o.c.model + ' [model_id ' + o.c.group_id + '] | колір: ' + (o.x.color || 'невідомо') + ' | ' + o.c.price + ' грн | є розміри: ' + (o.c.sizes_in_stock || 'немає в наявності') + (wantSize ? (hasSize(o.c) ? ' | розмір ' + wantSize + ' Є' : ' | розміру ' + wantSize + ' немає') : '') + (isGtx(o.c) ? ' | водостійка (Gore-Tex)' : '');
const top = rows.slice(0, 6);
let brandMissing = false;
if (custBrand && !/^(невідомо|unknown|none|n\/a|-)$/i.test(custBrand)) {
  const b = custBrand.toLowerCase();
  brandMissing = !$('Get cached catalog').all().some(i => String(i.json.model || '').toLowerCase().includes(b));
}
const seen = 'Що бачу на фото клієнта: ' + (custBrand ? 'бренд ' + custBrand + ', ' : '') + 'колір: ' + (custColors || 'невідомо') + '.' + (custWP ? ' Клієнт шукає ВОДОСТІЙКЕ взуття (є позначка на фото).' : '') + (custWarm ? ' Є позначка «термо» (утеплене).' : '') + (brandMissing ? ' УВАГА: бренду «' + custBrand + '» у каталозі немає взагалі.' : '');
const brandRule = brandMissing ? ' 5) ОБОВ’ЯЗКОВО спершу чесно скажи клієнту, що бренду «' + custBrand + '» у каталозі немає, і лише після цього запропонуй найближчі схожі моделі (бажано з потрібним розміром).' : '';
const wpRule = custWP ? ' 6) Клієнт шукає водостійке: водостійкими вважай ЛИШЕ моделі з позначкою «водостійка (Gore-Tex)», обов’язково скажи про це; для решти скажи, що водостійкість підтвердити не можу.' : '';
const warmRule = custWarm ? ' 7) Про утеплення нічого не стверджуй: дані про утеплювач у каталозі відсутні, їх уточнить менеджер.' : '';
const rule = '\nПРАВИЛА ПОДАЧІ: Розпізнавання за фото не гарантує точності, тому НІКОЛИ не стверджуй, що це саме та модель. 1) Якщо є ВІРОГІДНІ ЗБІГИ — пропонуй насамперед їх (до 2–3): надішли фото кожної (send_photo), назви назву, колір, ціну і розміри в наявності, і спитай «Це ця модель?». 2) Якщо клієнтського розміру немає у вірогідного збігу — скажи це чесно, пропонуй інші розміри цієї моделі, потім ТУ САМУ МОДЕЛЬ ІНШОГО КОЛЬОРУ з потрібним розміром. 3) Лише якщо і тієї ж моделі немає взагалі — запропонуй СХОЖІ (у списку вже першими йдуть ті, де є потрібний розмір), чітко сказавши, що це інші моделі. 4) Нічого не вигадуй, використовуй лише цей список. Ніколи не показуй клієнту model_id.' + brandRule + wpRule + warmRule;
const none = 'Не вдалося надійно знайти цю модель у каталозі. ' + seen + ' Чесно скажи клієнту, що не можеш однозначно визначити модель, і попроси назву моделі або чіткіше фото; запропонуй передати менеджеру.';
const result = top.length ? seen + '\n' + top.map(fmt).join('\n') + rule : none;
return [{ json: { result } }];

const url = $('Photo request').first().json.image_url;
let b64 = '';
try {
  const buf = await this.helpers.httpRequest({ url, encoding: 'arraybuffer', json: false });
  b64 = Buffer.from(buf).toString('base64');
} catch (e) {}
return [{ json: { mime: 'image/jpeg', b64 } }];

