={{ (() => { const cust = $('Fetch customer photo').first().json; const urls = String($json.imageUrls).split(','); const prompt = 'Фото 1 — взуття, яке хоче клієнт (може бути скріншот допису з накладеним текстом). Далі фото кандидатів з каталогу в порядку:
' + $json.list + '

Спочатку опиши колір взуття на фото 1 (основні кольори англійською). Якщо бренд видно на самому взутті, на логотипі чи в тексті допису, вкажи його в customer_brand (інакше порожній рядок; не вгадуй). ПРОЧИТАЙ накладений на фото текст і ярлики: customer_waterproof=true, якщо є ознаки водостійкості («водостійкі», «водонепроникні», waterproof, GORE-TEX); customer_warm=true, якщо є «термо», «утеплені», хутро; інакше false. Ігноруй руки й тло. Потім для КОЖНОГО кандидата окремо відповіді на два питання: (a) same_model — чи це ТА САМА модель взуття, що на фото 1 (порівнюй конструкцію: форму підошви, шнурівку, язик, логотипи, панелі, матеріал, не колір); (b) same_colorway — чи абсолютно такий же колір і розміщення кольорів (наприклад, білий ≠ чорний ≠ бежевий). Будь суворим: сумніваєшся — false. Якщо жодна модель не схожа, поверни всім false. similar_style=true лише якщо силует і тип взуття (тип, висота, підошва) реально близькі. Поверни ЛИШЕ JSON: {"customer_brand":"","customer_colors":"...","customer_waterproof":false,"customer_warm":false,"items":[{"n":1,"same_model":true,"same_colorway":false,"color":"колір кандидата українською","similar_style":true}]}'; const content = [{ type: 'text', text: prompt }, { type: 'image_url', image_url: { url: cust.b64 ? 'data:image/jpeg;base64,' + cust.b64 : urls[0] } }]; urls.slice(1).forEach(u => content.push({ type: 'image_url', image_url: { url: u } })); return JSON.stringify({ model: 'gpt-6.1-terra', messages: [{ role: 'user', content }], max_completion_tokens: 4000, response_format: { type: 'json_object' } }); })() }}

