const r = $input.first().json;
const t = (r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content) || '';
return [{ json: { content: { parts: [{ text: t }] } } }];

const r = String($input.first().json.result || '')
  .replace('надішли фото кожної (send_photo)', 'надішли фото ЛИШЕ однієї, найвірогіднішої моделі (send_photo один раз); інші кольори чи моделі опиши ТЕКСТОМ (колір і розміри) і запропонуй показати фото')
  .replace('Ніколи не показуй клієнту model_id.', 'Одразу після назви кожної моделі в своїй відповіді пиши тег [model_id N] — він видаляється автоматично, клієнт його не бачить.');
return [{ json: { result: r } }];
